// ── Push Notification Subscription ──────────────────────────────────────────
// Called after a successful family login with the family's UUID.
// Shows a soft in-page prompt (not the native browser dialog) so parents
// can opt in without being surprised.

// Paste the VAPID public key generated by scripts/generate-vapid-keys.js
const VAPID_PUBLIC_KEY = 'REPLACE_WITH_YOUR_VAPID_PUBLIC_KEY';

async function initPushNotifications(familyId) {
  if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) return;
  if (Notification.permission === 'denied') return;
  if (!VAPID_PUBLIC_KEY || VAPID_PUBLIC_KEY.startsWith('REPLACE')) return;

  const reg = await navigator.serviceWorker.ready;

  // Already subscribed — re-save in case it's a new device
  const existing = await reg.pushManager.getSubscription();
  if (existing) {
    savePushSubscription(existing, familyId);
    return;
  }

  // Don't re-show the prompt if they dismissed it this session
  if (sessionStorage.getItem('push-dismissed')) return;

  showPushPrompt(familyId, reg);
}

function showPushPrompt(familyId, reg) {
  if (document.getElementById('push-prompt')) return; // already shown

  const banner = document.createElement('div');
  banner.id = 'push-prompt';
  banner.innerHTML = `
    <div class="push-prompt-inner">
      <span class="push-prompt-text">🔔 Get notified about your care days and school closures?</span>
      <div class="push-prompt-btns">
        <button id="push-allow-btn"   class="btn-primary btn-sm">Allow</button>
        <button id="push-dismiss-btn" class="btn-ghost  btn-sm">No thanks</button>
      </div>
    </div>
  `;
  document.body.appendChild(banner);

  document.getElementById('push-allow-btn').addEventListener('click', async () => {
    banner.remove();
    try {
      const sub = await reg.pushManager.subscribe({
        userVisibleOnly:      true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
      });
      await savePushSubscription(sub, familyId);
    } catch (err) {
      console.warn('Push subscription failed:', err);
    }
  });

  document.getElementById('push-dismiss-btn').addEventListener('click', () => {
    banner.remove();
    sessionStorage.setItem('push-dismissed', '1');
  });
}

async function savePushSubscription(sub, familyId) {
  const { endpoint, keys: { p256dh, auth } } = sub.toJSON();
  try {
    await fetch('/push-subscribe', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({ family_id: familyId, endpoint, p256dh, auth }),
    });
  } catch (err) {
    console.warn('Failed to save push subscription:', err);
  }
}

// Convert VAPID public key from base64url to Uint8Array for pushManager.subscribe
function urlBase64ToUint8Array(b64url) {
  const pad  = '='.repeat((4 - b64url.length % 4) % 4);
  const b64  = (b64url + pad).replace(/-/g, '+').replace(/_/g, '/');
  const raw  = atob(b64);
  return Uint8Array.from([...raw].map(c => c.charCodeAt(0)));
}
